import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart, type CartConfig } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

describe("Cart", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  describe("add", () => {
    it("adds a product to the cart", () => {
      cart.add(makeProduct(), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding the same product again", () => {
      const product = makeProduct();
      cart.add(product, 2);
      cart.add(product, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("throws for non-positive quantity", () => {
      expect(() => cart.add(makeProduct(), 0)).toThrow(RangeError);
      expect(() => cart.add(makeProduct(), -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      expect(() => cart.add(makeProduct(), 1.5)).toThrow(RangeError);
    });

    it("throws for negative unitPriceCents", () => {
      expect(() => cart.add(makeProduct({ unitPriceCents: -1 }), 1)).toThrow(
        RangeError,
      );
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      cart.add(makeProduct(), 1);
      expect(cart.remove("p1")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing line", () => {
      cart.add(makeProduct(), 2);
      cart.updateQuantity("p1", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes the line when quantity is set to 0", () => {
      cart.add(makeProduct(), 2);
      cart.updateQuantity("p1", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for negative quantity", () => {
      cart.add(makeProduct(), 1);
      expect(() => cart.updateQuantity("p1", -1)).toThrow(RangeError);
    });

    it("throws for non-integer quantity", () => {
      cart.add(makeProduct(), 1);
      expect(() => cart.updateQuantity("p1", 2.5)).toThrow(RangeError);
    });

    it("throws for unknown product id", () => {
      expect(() => cart.updateQuantity("unknown", 1)).toThrow(
        "Product unknown is not in the cart",
      );
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      cart.add(makeProduct(), 3);
      cart.add(makeProduct({ id: "p2" }), 2);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy of lines", () => {
      cart.add(makeProduct(), 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals — default config (no discount, no tax, free shipping)", () => {
    it("computes subtotal as sum of price * quantity", () => {
      cart.add(makeProduct({ id: "a", unitPriceCents: 500 }), 3);
      cart.add(makeProduct({ id: "b", unitPriceCents: 1200 }), 1);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(2700);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(2700);
    });

    it("returns all zeros for empty cart", () => {
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });
  });

  describe("totals — pricing pipeline with mocked seams", () => {
    it("applies discount, then tax on discounted subtotal, then shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };

      const cart = new Cart({
        discountPolicy,
        taxCalculator,
        shippingCalculator,
        region: "US-CA",
      });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 2);

      const t = cart.totals();
      expect(t.subtotalCents).toBe(2000);
      expect(t.discountCents).toBe(200);

      // tax is called with discounted subtotal (2000 - 200 = 1800)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1800, "US-CA");
      expect(t.taxCents).toBe(80);

      // shipping is called with lines and discounted subtotal
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        1800,
      );
      expect(t.shippingCents).toBe(500);

      // total = discountedSubtotal + tax + shipping = 1800 + 80 + 500
      expect(t.totalCents).toBe(2380);
    });

    it("clamps discount to [0, subtotal]", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(99999),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 500 }), 1);

      const t = cart.totals();
      expect(t.discountCents).toBe(500);
      expect(t.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 500 }), 1);

      const t = cart.totals();
      expect(t.discountCents).toBe(0);
      expect(t.totalCents).toBe(500);
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(makeProduct({ unitPriceCents: 500 }), 1);

      const t = cart.totals();
      expect(t.taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(makeProduct({ unitPriceCents: 500 }), 1);

      const t = cart.totals();
      expect(t.shippingCents).toBe(0);
    });

    it("defaults region to US", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator });
      cart.add(makeProduct(), 1);
      cart.totals();
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(
        expect.any(Number),
        "US",
      );
    });
  });

  describe("checkout", () => {
    it("returns totals and lines without collaborators", async () => {
      cart.add(makeProduct({ unitPriceCents: 500 }), 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });

    describe("price refresh", () => {
      it("uses refreshed prices from PriceFetcher", async () => {
        cart.add(makeProduct({ id: "a", unitPriceCents: 100 }), 2);
        const priceFetcher: PriceFetcher = {
          fetchPriceCents: vi
            .fn<(id: string) => Promise<number>>()
            .mockResolvedValue(200),
        };
        const result = await cart.checkout({ priceFetcher });
        // refreshed: 200 * 2 = 400
        expect(result.totals.subtotalCents).toBe(400);
        expect(result.lines[0]!.product.unitPriceCents).toBe(200);
      });

      it("propagates PriceFetcher rejection", async () => {
        cart.add(makeProduct(), 1);
        const priceFetcher: PriceFetcher = {
          fetchPriceCents: vi
            .fn<(id: string) => Promise<number>>()
            .mockRejectedValue(new Error("price service down")),
        };
        await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
          "price service down",
        );
      });
    });

    describe("inventory check", () => {
      it("passes when all items are available", async () => {
        cart.add(makeProduct({ id: "a" }), 2);
        const inventoryChecker: InventoryChecker = {
          check: vi
            .fn<(id: string, qty: number) => Promise<{ available: boolean }>>()
            .mockResolvedValue({ available: true }),
        };
        const result = await cart.checkout({ inventoryChecker });
        expect(result.totals.subtotalCents).toBe(2000);
      });

      it("throws InventoryError when item is unavailable", async () => {
        cart.add(makeProduct({ id: "x" }), 3);
        const inventoryChecker: InventoryChecker = {
          check: vi
            .fn<(id: string, qty: number) => Promise<{ available: boolean; reason?: string }>>()
            .mockResolvedValue({
              available: false,
              reason: "discontinued",
            }),
        };
        try {
          await cart.checkout({ inventoryChecker });
          expect.fail("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("x");
          expect(invErr.requested).toBe(3);
          expect(invErr.message).toBe("discontinued");
        }
      });

      it("throws InventoryError on partial-stock denial", async () => {
        cart.add(makeProduct({ id: "y" }), 10);
        const inventoryChecker: InventoryChecker = {
          check: vi
            .fn<(id: string, qty: number) => Promise<{ available: boolean; availableQuantity?: number }>>()
            .mockResolvedValue({
              available: true,
              availableQuantity: 5,
            }),
        };
        try {
          await cart.checkout({ inventoryChecker });
          expect.fail("should have thrown");
        } catch (err) {
          expect(err).toBeInstanceOf(InventoryError);
          const invErr = err as InventoryError;
          expect(invErr.productId).toBe("y");
          expect(invErr.requested).toBe(10);
          expect(invErr.available).toBe(5);
        }
      });

      it("does not throw when availableQuantity >= requested", async () => {
        cart.add(makeProduct({ id: "z" }), 3);
        const inventoryChecker: InventoryChecker = {
          check: vi
            .fn<(id: string, qty: number) => Promise<{ available: boolean; availableQuantity?: number }>>()
            .mockResolvedValue({
              available: true,
              availableQuantity: 5,
            }),
        };
        const result = await cart.checkout({ inventoryChecker });
        expect(result.totals.subtotalCents).toBe(3000);
      });
    });

    describe("async tax provider", () => {
      it("uses async tax provider for tax computation", async () => {
        const discountPolicy: DiscountPolicy = {
          computeDiscountCents: vi.fn().mockReturnValue(200),
        };
        const shippingCalculator: ShippingCalculator = {
          computeShippingCents: vi.fn().mockReturnValue(500),
        };
        const cart = new Cart({
          discountPolicy,
          shippingCalculator,
          region: "US",
        });
        cart.add(makeProduct({ unitPriceCents: 1000 }), 2);

        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn<(region: string) => Promise<number>>().mockResolvedValue(0.1),
        };

        const result = await cart.checkout({ asyncTaxProvider });
        // subtotal=2000, discount=200, discounted=1800, tax=10% of 1800=180
        expect(result.totals.subtotalCents).toBe(2000);
        expect(result.totals.discountCents).toBe(200);
        expect(result.totals.taxCents).toBe(180);
        expect(result.totals.shippingCents).toBe(500);
        expect(result.totals.totalCents).toBe(1800 + 180 + 500);
      });

      it("propagates async tax provider failure", async () => {
        const cart = new Cart({ region: "US" });
        cart.add(makeProduct(), 1);
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi
            .fn<(region: string) => Promise<number>>()
            .mockRejectedValue(new Error("rate service down")),
        };
        await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
          "rate service down",
        );
      });
    });

    describe("full pipeline with all collaborators", () => {
      it("refresh → inventory → async tax all compose", async () => {
        cart.add(makeProduct({ id: "a", unitPriceCents: 100 }), 2);

        const priceFetcher: PriceFetcher = {
          fetchPriceCents: vi
            .fn<(id: string) => Promise<number>>()
            .mockResolvedValue(500),
        };
        const inventoryChecker: InventoryChecker = {
          check: vi
            .fn<(id: string, qty: number) => Promise<{ available: boolean; availableQuantity?: number }>>()
            .mockResolvedValue({ available: true, availableQuantity: 100 }),
        };
        const asyncTaxProvider: AsyncTaxRateProvider = {
          getRate: vi.fn<(region: string) => Promise<number>>().mockResolvedValue(0.05),
        };

        const result = await cart.checkout({
          priceFetcher,
          inventoryChecker,
          asyncTaxProvider,
        });

        // Refreshed: 500 * 2 = 1000
        expect(result.totals.subtotalCents).toBe(1000);
        // Default no discount → 0
        expect(result.totals.discountCents).toBe(0);
        // 5% tax on 1000 = 50
        expect(result.totals.taxCents).toBe(50);
        // Default free shipping → 0
        expect(result.totals.shippingCents).toBe(0);
        expect(result.totals.totalCents).toBe(1050);
      });
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
    [999999, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "percent must be between 0 and 100"],
      [101, "percent must be between 0 and 100"],
      [NaN, "percent must be between 0 and 100"],
      [Infinity, "percent must be between 0 and 100"],
    ])("rejects invalid percent %s", (percent, msg) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 → 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down fractional cents (10% of 1001 → 100)", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1001)).toBe(100);
    });

    it("100% discount returns full subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("handles large subtotal", () => {
      const policy = new PercentageDiscountPolicy(15);
      // 15% of 1_000_000 = 150_000
      expect(policy.computeDiscountCents(1_000_000)).toBe(150_000);
    });

    it("rounds down: 33% of 100 → 33 not 33.0", () => {
      const policy = new PercentageDiscountPolicy(33);
      expect(policy.computeDiscountCents(100)).toBe(33);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });

    it("accepts positive integer", () => {
      expect(() => new FixedAmountDiscountPolicy(500)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(2000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact subtotal when fixed amount equals subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(1000);
      expect(policy.computeDiscountCents(1000)).toBe(1000);
    });

    it("zero discount returns 0", () => {
      const policy = new FixedAmountDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from multiple policies against the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, plus fixed 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child discount to 0 in sum", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(50)],
        "sum",
      );
      // max(0, -100) + 50 = 50
      expect(composite.computeDiscountCents(1000)).toBe(50);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("can exceed subtotal (clamping is done by Cart)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(600), new FixedAmountDiscountPolicy(600)],
        "sum",
      );
      // Each caps at 1000, sum = 2000 — Composite does NOT clamp, Cart does
      expect(composite.computeDiscountCents(1000)).toBe(2000);
    });

    it("defaults to sum mode when mode is not specified", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // 10% of 1000 = 100, remaining = 900, then fixed 200 from 900 → total discount = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("ordering matters in chain mode", () => {
      const composite1 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // 50% of 1000=500, remaining=500, 50% of 500=250, total=750
      expect(composite1.computeDiscountCents(1000)).toBe(750);

      const composite2 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "sum",
      );
      // sum: 500 + 500 = 1000
      expect(composite2.computeDiscountCents(1000)).toBe(1000);
    });

    it("chain caps each step at remaining", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(800), new FixedAmountDiscountPolicy(800)],
        "chain",
      );
      // First: min(800, 1000) = 800, remaining=200. Second: min(800, 200) = 200. Total = 1000
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal in chain", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child discount to 0 in chain", () => {
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // max(0, -50)=0 capped to min(0, 1000)=0, remaining=1000, then 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });
  });
});

