describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 2000, costCents: 700 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: -100, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 100.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 100, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 100, costCents: 5.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            99.5,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets and overflow", () => {
      expect(
        () => new WeightBasedShippingCalculator(brackets, 2000),
      ).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [makeLine({ weightGrams: undefined }, 3)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 400g → bracket 500g → 300 cents
      const lines = [makeLine({ weightGrams: 400 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // exactly 500g → first bracket
      const lines = [makeLine({ weightGrams: 500 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("selects next bracket when just over boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 501g → bracket 2000g → 700 cents
      const lines = [makeLine({ weightGrams: 501 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });

    it("selects the last bracket at its exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 5000g exactly → bracket 5000g → 1200 cents
      const lines = [makeLine({ weightGrams: 2500 }, 2)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      // 6000g > 5000g → overflow 2000 cents
      const lines = [makeLine({ weightGrams: 3000 }, 2)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(2000);
    });

    it("falls back to heaviest bracket cost when no overflow is specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 6000g > 5000g → last bracket cost = 1200
      const lines = [makeLine({ weightGrams: 6000 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(1200);
    });

    it("sorts unsorted brackets correctly", () => {
      const unsorted: WeightBracket[] = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      // 400g → should hit 500g bracket → 300
      const lines = [makeLine({ weightGrams: 400 }, 1)];
      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 200*2 + 300*1 = 700g → bracket 2000 → 700 cents
      const lines = [
        makeLine({ weightGrams: 200 }, 2),
        makeLine({ id: "p2", weightGrams: 300 }, 1),
      ];
      expect(calc.computeShippingCents(lines, 1000)).toBe(700);
    });
  });
});

