import { describe, it, expect } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine, Product } from "../src/product.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "US"],
    [5000, "FR"],
    [-100, "GB"],
  ])("computeTaxCents(%i, %s) returns 0", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects default rate below 0", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects default rate above 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects NaN default rate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
    });

    it("rejects rate map entry below 0", () => {
      expect(() => new RegionalTaxCalculator({ US: -0.01 })).toThrow(RangeError);
    });

    it("rejects rate map entry above 1", () => {
      expect(() => new RegionalTaxCalculator({ US: 1.5 })).toThrow(RangeError);
    });

    it("rejects NaN rate map entry", () => {
      expect(() => new RegionalTaxCalculator({ US: NaN })).toThrow(RangeError);
    });

    it("accepts valid rates", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 0.0875, FR: 0.2 }, 0.1),
      ).not.toThrow();
    });

    it("accepts boundary rates 0 and 1", () => {
      expect(
        () => new RegionalTaxCalculator({ ZERO: 0, FULL: 1 }, 0),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it("uses the region-specific rate", () => {
      // 8.75% of 10000 = 875
      expect(calc.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 10000 = 500
      expect(calc.computeTaxCents(10000, "JP")).toBe(500);
    });

    it("rounds down fractional cents", () => {
      // 20% of 1001 = 200.2 → 200
      expect(calc.computeTaxCents(1001, "FR")).toBe(200);
    });

    it("returns 0 for zero taxable", () => {
      expect(calc.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(calc.computeTaxCents(-100, "US-CA")).toBe(0);
    });

    it("default rate 0 means no tax for unknown regions", () => {
      const calc0 = new RegionalTaxCalculator({ US: 0.1 });
      expect(calc0.computeTaxCents(1000, "XX")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for zero taxable without calling provider", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => {
        throw new Error("should not be called");
      },
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => {
        throw new Error("should not be called");
      },
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("computes tax using the async rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.1,
    };
    const calc = new AsyncTaxCalculator(provider);
    // 10% of 2000 = 200
    expect(await calc.computeTaxCents(2000, "US")).toBe(200);
  });

  it("rounds down fractional cents", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.0875,
    };
    const calc = new AsyncTaxCalculator(provider);
    // 8.75% of 1001 = 87.5875 → 87
    expect(await calc.computeTaxCents(1001, "US")).toBe(87);
  });

  it("throws RangeError for rate above 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 1.5,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => -0.1,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError for NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => NaN,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => {
        throw new Error("network failure");
      },
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "network failure",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight * quantity across lines", () => {
    const lines: CartLine[] = [
      { product: makeProduct({ weightGrams: 200 }), quantity: 3 },
      { product: makeProduct({ id: "p2", weightGrams: 500 }), quantity: 2 },
    ];
    // 200*3 + 500*2 = 600 + 1000 = 1600
    expect(totalLineWeightGrams(lines)).toBe(1600);
  });

  it("treats undefined weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: makeProduct({ weightGrams: undefined }), quantity: 5 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("handles mixed weighted and unweighted products", () => {
    const lines: CartLine[] = [
      { product: makeProduct({ weightGrams: 300 }), quantity: 2 },
      { product: makeProduct({ id: "p2" }), quantity: 4 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(600);
  });
});

