+    it("selects the first bracket that covers the weight", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // 400g → bracket 500g → 300 cents
+      const lines = [makeLine({ weightGrams: 400 }, 1)];
+      expect(calc.computeShippingCents(lines, 1000)).toBe(300);
+    });
