import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine, Product } from "../src/product.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return { id: "p1", name: "Widget", unitPriceCents: 1000, ...overrides };
}

describe("InventoryError", () => {
  it("exposes productId, requested, and available properties", () => {
    const err = new InventoryError("out of stock", "abc", 5, 2);
    expect(err.message).toBe("out of stock");
    expect(err.productId).toBe("abc");
    expect(err.requested).toBe(5);
    expect(err.available).toBe(2);
    expect(err.name).toBe("InventoryError");
    expect(err).toBeInstanceOf(Error);
  });

  it("handles undefined available", () => {
    const err = new InventoryError("gone", "xyz", 3, undefined);
    expect(err.available).toBeUndefined();
    expect(err.requested).toBe(3);
  });
});

describe("refreshPrices", () => {
  it("updates unitPriceCents from the fetcher", async () => {
    const lines: CartLine[] = [
      { product: makeProduct({ id: "a", unitPriceCents: 100 }), quantity: 2 },
      { product: makeProduct({ id: "b", unitPriceCents: 200 }), quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn<(id: string) => Promise<number>>()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };

    const result = await refreshPrices(lines, fetcher);
    expect(result).toHaveLength(2);
    expect(result[0]!.product.unitPriceCents).toBe(150);
    expect(result[0]!.quantity).toBe(2);
    expect(result[1]!.product.unitPriceCents).toBe(250);
    expect(result[1]!.quantity).toBe(1);
  });

  it("preserves other product properties", async () => {
    const lines: CartLine[] = [
      {
        product: makeProduct({
          id: "a",
          name: "Gadget",
          weightGrams: 500,
          currency: "EUR",
        }),
        quantity: 1,
      },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn<(id: string) => Promise<number>>().mockResolvedValue(999),
    };

    const result = await refreshPrices(lines, fetcher);
    expect(result[0]!.product.name).toBe("Gadget");
    expect(result[0]!.product.weightGrams).toBe(500);
    expect(result[0]!.product.currency).toBe("EUR");
    expect(result[0]!.product.unitPriceCents).toBe(999);
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn<(id: string) => Promise<number>>(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("throws RangeError for negative fetched price", async () => {
    const lines: CartLine[] = [
      { product: makeProduct({ id: "a" }), quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn<(id: string) => Promise<number>>().mockResolvedValue(-5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const lines: CartLine[] = [
      { product: makeProduct({ id: "a" }), quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn<(id: string) => Promise<number>>().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("propagates fetcher rejection", async () => {
    const lines: CartLine[] = [
      { product: makeProduct({ id: "a" }), quantity: 1 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn<(id: string) => Promise<number>>()
        .mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("fetch failed");
  });

  it("does not mutate the original lines", async () => {
    const original: CartLine[] = [
      { product: makeProduct({ id: "a", unitPriceCents: 100 }), quantity: 2 },
    ];
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn<(id: string) => Promise<number>>().mockResolvedValue(200),
    };
    await refreshPrices(original, fetcher);
    expect(original[0]!.product.unitPriceCents).toBe(100);
  });
});

